// CPACK -> sparkplug-agent raw-tag tee (ADR-0042 P1). Place on a SECOND wire
// off the PLC-read node (a tee, not a redirect). Set CPACK_AGENT_INGEST_KEY as
// a flow/env var (never in the flow file); CPACK_AGENT_INGEST_URL is preset.
const key = env.get("CPACK_AGENT_INGEST_KEY");
if (!key) { node.error("CPACK_AGENT_INGEST_KEY env var not set - refusing to POST", msg); return null; }
const PREFIX = "CPACK/SC/LINHAS";
let readings = msg.payload;
if (!Array.isArray(readings)) {
    readings = [{ topic: msg.topic, value: (msg.payload && msg.payload.value !== undefined) ? msg.payload.value : msg.payload }];
}
const tags = [];
for (const r of readings) {
    if (!r || typeof r.topic !== "string" || r.value === undefined || r.value === null) continue;
    if (!r.topic.startsWith(PREFIX)) continue;
    const suffix = r.topic.slice(PREFIX.length);
    if (suffix === "") continue;
    const tag = { metric: suffix, value: r.value };
    if (r.quality === false) tag.q = false;
    if (Number.isInteger(r.value) && /StateCurrent$/.test(suffix)) tag.long = true;
    if (r.ts) tag.ts = r.ts;
    tags.push(tag);
}
if (tags.length === 0) { node.warn("cpack tee: no CPACK/SC/LINHAS tags; skipping"); return null; }
msg.payload = { group: "CPACK", endpoint: "cpack-edge", scan_ts: Date.now(), tags: tags };
msg.headers = { "Content-Type": "application/json", "X-Ingest-Key": key };
msg.url = env.get("CPACK_AGENT_INGEST_URL");
msg.method = "POST";
return msg;
